class Solution {
public:
    int duplicateNumbersXOR(vector<int>& nums) {
        unordered_set<int> seen;
        int ans = 0;
        for (int x : nums) {
            if (seen.count(x)) {
                ans ^= x;
            } else {
                seen.insert(x);
            }
        }
        return ans;
    }
};

class Solution {
    public int duplicateNumbersXOR(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        int ans = 0;
        for (int x : nums) {
            if (seen.contains(x)) {
                ans ^= x;
            } else {
                seen.add(x);
            }
        }
        return ans;
    }
}

var duplicateNumbersXOR = function(nums) {
    const seen = new Set();
